mapper.update:
UPDATE fields
SET label = #{label}
WHERE id = #{fieldId}
  AND form_id = #{formId}
  AND space_id = #{spaceId}
  AND event_id = #{eventId}

mapper.delete:
DELETE FROM fields
WHERE id = #{fieldId}
  AND form_id = #{formId}
  AND space_id = #{spaceId}
  AND event_id = #{eventId}
  AND kind = 'CUSTOM'
